<h1>Clientes</h1><div class="global-table"><table><thead><tr><th>Nome</th><th>Identificador</th><th>GDA</th><th>Status</th><th>Administrador</th><th>Caixas</th><th>Participantes</th><th>Criação</th><th>Última atividade</th><th>Ações</th></tr></thead><tbody><?php foreach($companies as$c):?><tr><td><?= htmlspecialchars($c['name']) ?></td><td><?= htmlspecialchars($c['identifier']) ?></td><td><?= htmlspecialchars($c['gda_client_id']??'—') ?></td><td><?= htmlspecialchars($c['status']) ?></td><td><?= htmlspecialchars($c['admin_name']??'—') ?></td><td><?= (int)$c['cycle_count'] ?></td><td><?= (int)$c['participant_count'] ?></td><td><?= htmlspecialchars($c['created_at']) ?></td><td><?= htmlspecialchars($c['last_activity']??'—') ?></td><td><a href="<?= global_url('/clientes/'.(int)$c['id']) ?>">Visualizar</a><form method="post" action="<?= global_url('/clientes/'.(int)$c['id'].'/'.($c['status']==='active'?'inativar':'ativar')) ?>" onsubmit="return confirm('Confirmar alteração do ambiente?')"><input type="hidden" name="csrf" value="<?= global_csrf() ?>"><button><?= $c['status']==='active'?'Inativar':'Ativar' ?></button></form><form method="post" action="<?= global_url('/clientes/'.(int)$c['id'].'/validar') ?>"><input type="hidden" name="csrf" value="<?= global_csrf() ?>"><button>Validar</button></form></td></tr><?php endforeach;?></tbody></table></div>
